arguments.command:
mkdir notes && cat > notes/PRC-501.md <<'EOF'
# PRC-501
`bin/price 999` prints 900; expected 899 (10% off, rounded down).
Cause: ee322d6 changed `$1*90/100` to `($1*90+99)/100` (rounds up) in bin/price, bin/quote, lib/invoice.sh.
Plan: add failing test for 999, revert the rounding in all three (README says all three share the rule).
EOF
cat > tests/price_test.sh <<'EOF'
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash -c 'source lib/invoice.sh' _ 999 2>/dev/null; bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
exit $fail
EOF
bash scripts/verify.sh; echo rc=$?
sed -i 's|(\$1 \* 90 + 99) / 100|$1 * 90 / 100|' bin/price bin/quote lib/invoice.sh
bash scripts/verify.sh; echo rc=$?; git diff --stat

